+/// `null` when the setup needs no other post, else the post, why, and
+/// the one call that takes it.
+pub(super) fn offer_view(world: &World, declared: Option<&str>) -> Value {
+    let Some(offer) = post_offer_for(world, declared) else {
+        return Value::Null;
